export const LOAD_LABELS = {
  total: "总重量", per_side: "每边配重", per_limb: "单边 / 每手", assistance: "辅助重量",
};

const number = (value, fallback = null) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

export function createSession(now = new Date()) {
  const startedAt = now.toISOString();
  return {
    schemaVersion: SCHEMA_VERSION,
    id: `qws_${now.getTime().toString(36)}_${cryptoRandom()}`,
    title: `${new Intl.DateTimeFormat("zh-CN", { month: "long", day: "numeric" }).format(now)} 力量训练`,
    startedAt, endedAt: "", timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "Asia/Taipei",
    sets: [], currentExerciseId: "", rest: null,
    timer: { running: false, elapsedMs: 0, startedAtMs: null },
    sync: { status: "local", draftId: "", workoutId: "" }, updatedAt: startedAt,
  };
}

function cryptoRandom() {
  const values = new Uint32Array(1);
  globalThis.crypto?.getRandomValues?.(values);
  return (values[0] || Math.floor(Math.random() * 2 ** 32)).toString(36);
}

export function normalizeSet(input) {
  const loadMode = ["total", "per_side", "per_limb", "assistance"].includes(input.loadMode) ? input.loadMode : "total";
  return {
    ...input,
    weightValue: Math.max(0, number(input.weightValue, 0)), weightUnit: input.weightUnit === "lb" ? "lb" : "kg",
    reps: Math.max(0, Math.round(number(input.reps, 0))),
    rir: input.rir === "" || input.rir == null ? null : Math.min(10, Math.max(0, number(input.rir, null))),
    rpe: input.rpe === "" || input.rpe == null ? null : Math.min(10, Math.max(1, number(input.rpe, null))),
    rer: input.rer === "" || input.rer == null ? null : Math.min(2, Math.max(.5, number(input.rer, null))),
    restSeconds: Math.min(7200, Math.max(0, Math.round(number(input.restSeconds, 0)))), loadMode,
    executionMode: ["left", "right", "alternating"].includes(input.side) ? "unilateral" : (input.executionMode || (loadMode === "per_limb" ? "bilateral_simultaneous" : "bilateral")),
    sideCount: loadMode === "per_side" || loadMode === "per_limb" ? (["left", "right"].includes(input.side) ? 1 : 2) : 1,
    notes: String(input.notes || "").slice(0, 1000), completedAt: input.completedAt || new Date().toISOString(),
  };
}

export function recordingModeForSet(input = {}) {
  if (input.loadMode !== "per_limb") return input.loadMode || "total";
  if (input.side === "left" || input.side === "right") return `per_limb_${input.side}`;
  if (input.side === "alternating") return "per_limb_alternating";
  return "per_limb_both";
}

export function applyRecordingMode(input, recordingMode) {
  const next = { ...input };
  if (recordingMode.startsWith("per_limb_")) {
    next.loadMode = "per_limb";
    next.side = recordingMode.slice("per_limb_".length);
    next.executionMode = ["left", "right", "alternating"].includes(next.side) ? "unilateral" : "bilateral_simultaneous";
    next.sideCount = ["left", "right"].includes(next.side) ? 1 : 2;
    return next;
  }
  next.loadMode = ["total", "per_side", "assistance"].includes(recordingMode) ? recordingMode : "total";
  next.side = "both";
  next.executionMode = next.loadMode === "per_side" ? "bilateral_simultaneous" : "bilateral";
  next.sideCount = next.loadMode === "per_side" ? 2 : 1;
  return next;
}

export function nextSetDraft(input) {
  const side = input.loadMode === "per_limb" && input.side === "right" ? "left"
    : input.loadMode === "per_limb" && input.side === "left" ? "right" : input.side;
  return normalizeSet({ ...input, side, id: "", completedAt: "" });
}

export function draftFromExerciseDefault(exercise, cached = null) {
  const unilateral = exercise.loadMode === "per_limb" && exercise.executionMode === "unilateral";
  const source = cached && typeof cached === "object" ? cached : {};
  return normalizeSet({
    exerciseId: exercise.id,
    exerciseName: exercise.name,
    canonicalNameEn: exercise.canonicalNameEn,
    equipment: exercise.equipment,
    movementPattern: exercise.movementPattern,
    loadMode: source.loadMode || exercise.loadMode,
    executionMode: source.executionMode || exercise.executionMode,
    sideCount: source.sideCount || exercise.sideCount,
    weightValue: source.weightValue ?? 10,
    weightUnit: source.weightUnit || "kg",
    reps: source.reps ?? 10,
    rir: source.rir ?? 2,
    rpe: source.rpe ?? null,
    restSeconds: source.restSeconds ?? 120,
    side: unilateral ? "right" : "both",
    gripWidth: source.gripWidth || "",
    gripOrientation: source.gripOrientation || "",
    notes: "",
  });
}

export function changeWeightUnit(input, targetUnit) {
  const sourceUnit = input.weightUnit === "lb" ? "lb" : "kg";
  const nextUnit = targetUnit === "lb" ? "lb" : "kg";
  if (sourceUnit === nextUnit) return normalizeSet({ ...input, weightUnit: nextUnit });
  const factor = sourceUnit === "kg" ? 2.2046226218 : 0.45359237;
  const weightValue = Math.round(number(input.weightValue, 0) * factor * 100) / 100;
  return normalizeSet({ ...input, weightValue, weightUnit: nextUnit });
}

export function decisiveWatchCandidate(candidates, threshold = .9) {
  const credible = (Array.isArray(candidates) ? candidates : []).filter((item) => (
    number(item?.matchConfidence, 0) >= threshold
    && (item?.reason || []).includes("message_time_within_workout")
    && (item?.reason || []).includes("strength_training_type")
  ));
  return credible.length === 1 ? credible[0] : null;
}

export function calculateSetVolume(set, bodyWeight = null) {
  const reps = number(set.reps, 0); const factor = set.weightUnit === "lb" ? 0.45359237 : 1; const weight = number(set.weightValue, 0) * factor;
  if (!reps) return 0;
  if (set.loadMode === "assistance") return bodyWeight == null ? null : Math.max(0, bodyWeight - weight) * reps;
  if (set.loadMode === "per_limb" && (set.left || set.right)) {
    return factor * (number(set.left?.weight, 0) * number(set.left?.reps, 0) + number(set.right?.weight, 0) * number(set.right?.reps, 0));
  }
  return weight * reps * (["per_side", "per_limb"].includes(set.loadMode) ? number(set.sideCount, 2) : 1);
}

export function timerElapsedMs(session, nowMs = Date.now()) {
  const timer = session?.timer || {};
  const stored = Math.max(0, number(timer.elapsedMs, 0));
  return timer.running && timer.startedAtMs ? stored + Math.max(0, nowMs - timer.startedAtMs) : stored;
}

export function restRemainingSeconds(rest, nowMs = Date.now()) {
  if (!rest) return 0;
  if (rest.running && rest.endsAt) return Math.max(0, Math.ceil((rest.endsAt - nowMs) / 1000));
  return Math.max(0, Math.ceil(number(rest.remainingSeconds, rest.durationSeconds || 0)));
}

export function createRunningRest(durationSeconds = 120, nowMs = Date.now()) {
  const duration = Math.max(0, Math.round(Number(durationSeconds) || 0));
  return { durationSeconds: duration, remainingSeconds: duration, running: duration > 0, endsAt: duration > 0 ? nowMs + duration * 1000 : null };
}

export function adjustRest(rest, deltaSeconds, nowMs = Date.now()) {
  if (!rest) return null;
  const remaining = Math.max(0, restRemainingSeconds(rest, nowMs) + Number(deltaSeconds || 0));
  if (!remaining) return null;
  return {
    ...rest,
    durationSeconds: Math.max(Number(rest.durationSeconds || 0), remaining),
    remainingSeconds: remaining,
    endsAt: rest.running ? nowMs + remaining * 1000 : null,
  };
}

export function withoutExercise(session, exerciseId) {
  return {
    ...session,
    sets: (session.sets || []).filter((set) => set.exerciseId !== exerciseId),
    currentExerciseId: session.currentExerciseId === exerciseId ? "" : session.currentExerciseId,
    rest: null,
  };
}

export function sessionSummary(session) {
  const exercises = new Set(session.sets.map((set) => set.exerciseId));
  const volumes = session.sets.map((set) => calculateSetVolume(set, session.bodyWeightKg)).filter((value) => value != null);
  return {
    exerciseCount: exercises.size, setCount: session.sets.length, reps: session.sets.reduce((sum, set) => sum + number(set.reps, 0), 0),
    volume: Math.round(volumes.reduce((sum, value) => sum + value, 0) * 10) / 10,
    durationMinutes: Math.max(0, Math.round(timerElapsedMs(session) / 60000)),
  };
}

function historyExerciseSummary(exercise = {}) {
  const sets = Array.isArray(exercise.sets) ? exercise.sets : [];
  const volume = sets.reduce((sum, set) => sum + number(set.calculated_volume, 0), 0);
  const maxWeight = sets.reduce((best, set) => Math.max(best, number(set.weight_value, number(set.weight_kg, 0))), 0);
  return {
    exerciseId: exercise.exerciseId || "",
    name: exercise.name || "",
    setCount: sets.length,
    reps: sets.reduce((sum, set) => sum + number(set.reps, 0), 0),
    volume: Math.round(volume * 10) / 10,
    maxWeight,
    weightUnit: sets.find((set) => set.weight_unit)?.weight_unit || "kg",
  };
}

export function compareWorkoutHistory(current, previous = null) {
  const currentExercises = (current?.exercises || []).map(historyExerciseSummary);
  const previousById = new Map((previous?.exercises || []).map((item) => {
    const summary = historyExerciseSummary(item);
    return [summary.exerciseId, summary];
  }));
  const currentSummary = current?.summary || {};
  const previousSummary = previous?.summary || {};
  return {
    volumeDelta: Math.round((number(currentSummary.volume, 0) - number(previousSummary.volume, 0)) * 10) / 10,
    setDelta: number(currentSummary.setCount, 0) - number(previousSummary.setCount, 0),
    repsDelta: number(currentSummary.reps, 0) - number(previousSummary.reps, 0),
    exercises: currentExercises.map((item) => {
      const prior = previousById.get(item.exerciseId);
      return {
        ...item,
        previous: prior || null,
        volumeDelta: Math.round((item.volume - number(prior?.volume, 0)) * 10) / 10,
        maxWeightDelta: Math.round((item.maxWeight - number(prior?.maxWeight, 0)) * 100) / 100,
      };
    }),
  };
}

export function buildBodyCandidate(session) {
  const grouped = new Map();
  session.sets.forEach((set) => {
    const exerciseId = canonicalExerciseId(set.exerciseId);
    if (!grouped.has(exerciseId)) grouped.set(exerciseId, []);
    grouped.get(exerciseId).push({ ...set, exerciseId });
  });
  const markdown = toMarkdown(session);
  const exercises = [...grouped.entries()].map(([exerciseId, sets], orderIndex) => ({
    exerciseCanonicalId: exerciseId, originalExerciseName: sets[0].exerciseName, displayName: sets[0].exerciseName,
    canonicalNameEn: sets[0].canonicalNameEn || "", movementPattern: sets[0].movementPattern || "", equipment: sets[0].equipment || "",
    orderIndex: orderIndex + 1, startTime: sets[0].completedAt, endTime: sets.at(-1).completedAt, timePrecision: "exact", notes: "",
    confidence: { exercise: 1 }, sets: sets.map((set, index) => {
      const item = normalizeSet({ ...set });
      const result = {
        setIndex: index + 1, setType: item.setType || "working", weightValue: item.weightValue, weightUnit: item.weightUnit || "kg",
        loadMode: item.loadMode, executionMode: item.executionMode || (item.loadMode === "per_limb" ? "bilateral_simultaneous" : "bilateral"),
        sideCount: item.sideCount, reps: item.reps, restSeconds: item.restSeconds || null, painScore: item.painScore ?? null,
        isFailure: Boolean(item.isFailure), completed: true, notes: item.notes, completedAt: item.completedAt,
        timestampPrecision: "exact", confidence: { overall: 1 },
      };
      ["rir", "rpe", "rer"].forEach((key) => { if (item[key] != null) result[key] = item[key]; });
      ["gripWidth", "gripOrientation"].forEach((key) => { if (item[key]) result[key] = item[key]; });
      if (item.loadMode === "per_limb") {
        result.left = item.left || { weight: item.weightValue, reps: item.side === "right" ? 0 : item.reps };
        result.right = item.right || { weight: item.weightValue, reps: item.side === "left" ? 0 : item.reps };
      }
      if (item.loadMode === "assistance") {
        result.assistanceWeight = item.weightValue;
        if (session.bodyWeightKg != null) {
          const factor = item.weightUnit === "lb" ? 0.45359237 : 1;
          result.bodyWeight = session.bodyWeightKg;
          result.effectiveLoad = Math.round(Math.max(0, session.bodyWeightKg - item.weightValue * factor) * 1000) / 1000;
        }
      }
      return result;
    }),
  }));
  return {
    sourceType: "manual", rawInput: markdown, normalizedInput: markdown, workoutType: "traditional_strength_training",
    sourceStartedAt: session.startedAt, sourceEndedAt: session.endedAt || new Date().toISOString(), messageTimes: [], exercises,
    confidence: { overall: 1 }, needsConfirmation: true, uncertainFields: [], warnings: [],
    summary: { ...sessionSummary(session) }, parserVersion: "quick-workout-pwa-v1",
  };
}

export function toMarkdown(session) {
  const lines = [`# ${session.title}`, "", `- 开始：${session.startedAt}`, `- 结束：${session.endedAt || "进行中"}`, ""];
  let last = "";
  session.sets.forEach((set) => {
    if (set.exerciseId !== last) { lines.push(`## ${set.exerciseName}`); last = set.exerciseId; }
    const time = new Intl.DateTimeFormat("zh-CN", { hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date(set.completedAt));
    const gripWidth = { wide: "宽距", medium: "中距", close: "窄距" }[set.gripWidth] || "";
    const gripOrientation = { pronated: "正握", supinated: "反握", neutral: "对握" }[set.gripOrientation] || "";
    const side = ({ left: "左侧", right: "右侧", alternating: "左右交替" })[set.side] || "";
    const extras = [side, gripWidth, gripOrientation, set.rir != null ? `RIR ${set.rir}` : "", set.rpe != null ? `RPE ${set.rpe}` : "", set.rer != null ? `RER ${set.rer}` : "", set.notes || ""].filter(Boolean).join(" · ");
    lines.push(`- ${time} ${LOAD_LABELS[set.loadMode] || "重量"} ${set.weightValue}${set.weightUnit || "kg"} × ${set.reps} 次${extras ? ` · ${extras}` : ""}`);
  });
  return lines.join("\n");
}

export function createExport(session) {
  return { schemaVersion: SCHEMA_VERSION, exportedAt: new Date().toISOString(), session: { ...session }, bodyOsCandidate: buildBodyCandidate(session) };
}

export function snapshotFromWorkoutUploads(rows = []) {
  const workoutHistory = [];
  for (const row of rows || []) {
    const payload = row?.payload || {};
    let session = payload.session && typeof payload.session === "object" ? payload.session : payload;
    let sets = Array.isArray(session?.sets) ? session.sets : [];
    if (!sets.length) {
      const exercises = payload.bodyOsCandidate?.exercises || session.bodyOsCandidate?.exercises || [];
      sets = exercises.flatMap((exercise) => (exercise.sets || []).map((item) => ({
        exerciseId: exercise.exerciseCanonicalId || exercise.exerciseId,
        exerciseName: exercise.displayName || exercise.originalExerciseName || exercise.name,
        weightValue: item.weightValue ?? item.weight_value,
        weightUnit: item.weightUnit || item.weight_unit || "kg",
        reps: item.reps,
        loadMode: item.loadMode || item.load_mode,
        setType: item.setType || item.set_type,
        completed: item.completed === false || item.completed === 0 ? 0 : 1,
      })));
    }
    if (!sets.length) continue;
    const grouped = new Map();
    for (const set of sets) {
      const id = canonicalExerciseId(set.exerciseId || set.exercise_id);
      if (!id) continue;
      const group = grouped.get(id) || { exerciseId: id, name: set.exerciseName || set.name || id, sets: [] };
      group.sets.push({
        set_number: group.sets.length + 1,
        set_type: set.setType || set.set_type || "working",
        weight_value: set.weightValue ?? set.weight_value,
        weight_unit: set.weightUnit || set.weight_unit || "kg",
        reps: set.reps,
        completed: set.completed === false || set.completed === 0 ? 0 : 1,
        load_mode: set.loadMode || set.load_mode,
        rir: set.rir,
        rpe: set.rpe,
        calculated_volume: calculateSetVolume(set, session.bodyWeightKg),
      });
      grouped.set(id, group);
    }
    if (!grouped.size) continue;
    workoutHistory.push({
      id: String(session.id || row.id || ""),
      startedAt: session.startedAt || row.session_started_at || "",
      endedAt: session.endedAt || "",
      activityType: "TraditionalStrengthTraining",
      source: "quick_workout_upload",
      exercises: [...grouped.values()],
    });
  }
  workoutHistory.sort((a, b) => String(b.startedAt).localeCompare(String(a.startedAt)));
  const exerciseDefaults = {};
  for (const workout of workoutHistory) {
    for (const exercise of workout.exercises || []) {
      if (!exercise.exerciseId || exerciseDefaults[exercise.exerciseId] || !exercise.sets?.length) continue;
      const heaviest = exercise.sets.reduce((best, item) => Number(item.weight_value || 0) > Number(best.weight_value || 0) ? item : best, exercise.sets[0]);
      exerciseDefaults[exercise.exerciseId] = {
        workoutId: workout.id,
        usedAt: workout.startedAt,
        setCount: exercise.sets.length,
        weightValue: heaviest.weight_value,
        weightUnit: heaviest.weight_unit || "kg",
        reps: heaviest.reps || 0,
      };
    }
  }
  return {
    schemaVersion: "body.os.training-snapshot.v1",
    generatedAt: new Date().toISOString(),
    source: "workout_uploads",
    today: {},
    exerciseDefaults,
    workoutHistory,
    exerciseProgress: {},
  };
}


export const LIFT_RANGE_DAYS = { week: 7, month: 30, quarter: 91, year: 365 };
export const LIFT_KG_TO_LB = 2.2046226218;

export function estimated1rmKg(weightKg, reps) {
  const weight = Number(weightKg), count = Number(reps);
  if (!Number.isFinite(weight) || weight <= 0 || !Number.isFinite(count) || count <= 0) return null;
  return Math.round(weight * (1 + count / 30) * 10000) / 10000;
}

export function displayLiftKg(kg, unit) {
  if (kg == null || !Number.isFinite(Number(kg))) return null;
  return Math.round(Number(kg) * (unit === "lb" ? LIFT_KG_TO_LB : 1) * 100) / 100;
}

export function workingSetWeightKg(item = {}) {
  if (String(item.set_type || item.setType || "working") === "warmup" || item.completed === 0) return null;
  const direct = Number(item.weight_kg);
  if (Number.isFinite(direct) && direct > 0) return Math.round(direct * 10000) / 10000;
  const value = Number(item.weight_value ?? item.weightValue);
  if (!Number.isFinite(value) || value <= 0) return null;
  const unit = item.weight_unit || item.weightUnit || "kg";
  return Math.round(value * (unit === "lb" ? 0.45359237 : 1) * 10000) / 10000;
}

export function summarizeLiftDay(date, sets, workoutId = "") {
  const clean = (sets || []).filter((item) => Number(item.weightKg) > 0);
  if (!clean.length) return null;
  const n = clean.length;
  const mean = (key) => Math.round(clean.reduce((sum, item) => sum + Number(item[key] || 0), 0) / n * 10000) / 10000;
  const meanEstimate = Math.round(clean.reduce((sum, item) => sum + (estimated1rmKg(item.weightKg, item.reps) || 0), 0) / n * 10000) / 10000;
  return {
    date, workoutId, setCount: n, sets: clean,
    weightKg: mean("weightKg"),
    reps: mean("reps"),
    volumeKg: mean("volumeKg"),
    estimated1rmKg: meanEstimate,
  };
}

export function progressSeriesForExercise(snapshot, exerciseId) {
  const id = canonicalExerciseId(exerciseId);
  const byDate = new Map();
  let name = snapshot?.exerciseProgress?.[id]?.name || id;
  for (const workout of snapshot?.workoutHistory || []) {
    for (const exercise of workout.exercises || []) {
      if (!historyExerciseMatches(exercise, id)) continue;
      name = exercise.name || name;
      const date = String(workout.startedAt || "").slice(0, 10);
      if (!date) continue;
      const day = byDate.get(date) || { date, workoutId: workout.id || "", sets: [] };
      (exercise.sets || []).forEach((item, index) => {
        const weightKg = workingSetWeightKg(item);
        if (weightKg == null) return;
        const reps = Number(item.reps || 0);
        day.sets.push({
          setNumber: item.set_number || item.setNumber || index + 1,
          weightKg, reps,
          volumeKg: Math.round(weightKg * Math.max(reps, 0) * 1000) / 1000,
          weightValue: item.weight_value ?? item.weightValue ?? weightKg,
          weightUnit: item.weight_unit || item.weightUnit || "kg",
        });
      });
      if (day.sets.length) byDate.set(date, day);
    }
  }
  let points = [...byDate.values()]
    .map((day) => summarizeLiftDay(day.date, day.sets, day.workoutId))
    .filter(Boolean)
    .sort((a, b) => a.date.localeCompare(b.date));
  if (!points.length) {
    const progress = snapshot?.exerciseProgress || {};
    const hit = progress[id]
      || Object.values(progress).find((item) => historyExerciseMatches({ exerciseId: item?.exerciseId || item?.id, name: item?.name }, id));
    if (hit?.points?.length) {
      name = hit.name || name;
      points = hit.points;
    }
  }
  return { name, points };
}

export function pointsInLiftRange(points, rangeKey, today = new Date()) {
  const days = LIFT_RANGE_DAYS[rangeKey] || 365;
  const end = new Date(today);
  end.setHours(12, 0, 0, 0);
  const start = new Date(end);
  start.setDate(start.getDate() - days);
  return (points || []).filter((point) => {
    const day = new Date(`${point.date}T12:00:00`);
    return !Number.isNaN(day.getTime()) && day >= start && day <= end;
  });
}

export function lookbackLiftDeltas(points) {
  const ordered = [...(points || [])].sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const result = { week: null, month: null, quarter: null, year: null };
  if (!ordered.length) return result;
  const latest = ordered.at(-1);
  const latestDate = new Date(`${latest.date}T12:00:00`);
  for (const [key, days] of Object.entries(LIFT_RANGE_DAYS)) {
    const cutoff = new Date(latestDate);
    cutoff.setDate(cutoff.getDate() - days);
    const prior = ordered.filter((item) => new Date(`${item.date}T12:00:00`) <= cutoff);
    if (!prior.length) continue;
    const before = prior.at(-1);
    result[key] = {
      days, fromDate: before.date, toDate: latest.date,
      deltaWeightKg: Math.round((Number(latest.weightKg) - Number(before.weightKg)) * 10000) / 10000,
      deltaEstimated1rmKg: latest.estimated1rmKg == null || before.estimated1rmKg == null ? null : Math.round((Number(latest.estimated1rmKg) - Number(before.estimated1rmKg)) * 10000) / 10000,
      deltaVolumeKg: Math.round((Number(latest.volumeKg || 0) - Number(before.volumeKg || 0)) * 10000) / 10000,
    };
  }
  return result;
}

export function liftIsoPeriod(dateStr, grain) {
  const date = new Date(`${dateStr}T12:00:00`);
  if (Number.isNaN(date.getTime())) return null;
  if (grain === "month") {
    const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
    return { key, label: `${date.getFullYear()}年${date.getMonth() + 1}月` };
  }
  if (grain === "year") return { key: String(date.getFullYear()), label: `${date.getFullYear()}年` };
  const utc = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate());
  const day = new Date(utc).getUTCDay() || 7;
  const thursday = new Date(utc);
  thursday.setUTCDate(thursday.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(thursday.getUTCFullYear(), 0, 1));
  const week = Math.ceil((((thursday - yearStart) / 86400000) + 1) / 7);
  const year = thursday.getUTCFullYear();
  return { key: `${year}-W${String(week).padStart(2, "0")}`, label: `${year}年第${week}周` };
}

export function aggregateLiftPoints(points, grain = "session") {
  if (!grain || grain === "session" || grain === "day") return [...(points || [])];
  const buckets = new Map();
  for (const point of points || []) {
    const period = liftIsoPeriod(point.date, grain);
    if (!period) continue;
    const bucket = buckets.get(period.key) || { key: period.key, label: period.label, items: [] };
    bucket.items.push(point);
    buckets.set(period.key, bucket);
  }
  return [...buckets.values()].sort((a, b) => a.key.localeCompare(b.key)).map((bucket) => {
    const items = bucket.items;
    const count = items.length;
    const mean = (field) => Math.round(items.reduce((sum, item) => sum + Number(item[field] || 0), 0) / count * 10000) / 10000;
    return {
      date: items.at(-1).date,
      periodKey: bucket.key,
      periodLabel: bucket.label,
      weightKg: mean("weightKg"),
      estimated1rmKg: mean("estimated1rmKg"),
      volumeKg: mean("volumeKg"),
      reps: mean("reps"),
      sessionCount: count,
      setCount: items.reduce((sum, item) => sum + Number(item.setCount || 0), 0),
      sets: [],
      workoutId: items.at(-1).workoutId || "",
    };
  });
}

export function liftPointMetric(point, metric = "weight") {
  if (metric === "e1rm") return point?.estimated1rmKg;
  if (metric === "volume") return point?.volumeKg;
  return point?.weightKg;
}

export function liftPointDetailMarkup(point, { unit = "kg", grain = "session", escapeHTML = (value) => String(value) } = {}) {
  if (!point) return "";
  const mean = displayLiftKg(point.weightKg, unit);
  const best = displayLiftKg(point.estimated1rmKg, unit);
  const volume = displayLiftKg(point.volumeKg, unit);
  const title = point.periodLabel || point.date;
  if (grain !== "session") {
    return `<header><div><strong>${escapeHTML(title)}</strong><small>${point.sessionCount || 0} 次 · 均重 ${mean} ${unit}</small></div><em>均容量 ${volume == null ? "—" : `${volume} ${unit}·次`}</em></header><p>切到「按次」可查看每一次里每一组的重量。</p>`;
  }
  const sets = point.sets || [];
  const setRows = sets.map((item, index) => {
    const shown = displayLiftKg(item.weightKg, unit);
    return `<li><span>第 ${escapeHTML(item.setNumber || index + 1)} 组</span><strong>${shown} ${unit} × ${item.reps || 0}</strong><em>${displayLiftKg(item.volumeKg, unit)} ${unit}·次</em></li>`;
  }).join("");
  return `<header><div><strong>${escapeHTML(point.date)}</strong><small>${point.setCount || sets.length} 组 · 当日均重 ${mean} ${unit}${best == null ? "" : ` · 估算 1RM ${best} ${unit}`}</small></div><em>均容量 ${volume == null ? "—" : `${volume} ${unit}·次`}</em></header>${setRows ? `<ol>${setRows}</ol>` : "<p>没有逐组记录</p>"}`;
}

export function liftChartMarkup(points, { unit = "kg", grain = "session", large = false, activeIndex = -1, escapeHTML = (value) => String(value) } = {}) {
  const weights = points.map((point) => displayLiftKg(point.weightKg, unit));
  let running = null;
  const bests = points.map((point) => {
    const value = displayLiftKg(point.estimated1rmKg, unit);
    running = value == null ? running : Math.max(running == null ? value : running, value);
    return running;
  });
  const volumes = points.map((point) => displayLiftKg(point.volumeKg, unit));
  if (!points.length || weights.every((value) => value == null)) return `<div class="empty">暂无重量曲线</div>`;
  const width = large ? 720 : 640, height = large ? 280 : 228;
  const pad = { l: 46, r: 40, t: 22, b: 36 };
  const lineValues = [...weights, ...bests].filter((value) => value != null);
  const minRaw = Math.min(...lineValues);
  const maxRaw = Math.max(...lineValues);
  const padY = Math.max((maxRaw - minRaw) * 0.18, maxRaw * 0.04, 0.5);
  const min = Math.max(0, minRaw - padY);
  const max = maxRaw + padY;
  const span = Math.max(max - min, 0.001);
  const volMax = Math.max(...volumes.map((value) => value || 0), 1);
  const innerW = width - pad.l - pad.r;
  const innerH = height - pad.t - pad.b;
  const xAt = (index) => pad.l + (points.length === 1 ? innerW / 2 : index * innerW / (points.length - 1));
  const yAt = (value) => pad.t + (max - value) / span * innerH;
  const yVol = (value) => pad.t + innerH - (Number(value || 0) / volMax) * innerH * 0.72;
  const barW = Math.max(6, Math.min(22, innerW / Math.max(points.length, 1) * 0.42));
  const pathFor = (series) => series.map((value, index) => value == null ? "" : `${series.slice(0, index).some((item) => item != null) ? "L" : "M"}${xAt(index).toFixed(1)},${yAt(value).toFixed(1)}`).filter(Boolean).join(" ");
  const weightLine = pathFor(weights);
  const bestLine = pathFor(bests);
  const area = `${weightLine} L${xAt(points.length - 1).toFixed(1)},${(height - pad.b).toFixed(1)} L${xAt(0).toFixed(1)},${(height - pad.b).toFixed(1)} Z`;
  const active = Math.max(0, Math.min(points.length - 1, activeIndex >= 0 ? activeIndex : points.length - 1));
  const ticks = [max, (max + min) / 2, min];
  const labelIndexes = points.length <= 6 ? points.map((_, index) => index) : [0, Math.round((points.length - 1) / 2), points.length - 1];
  const axisLabel = (point) => {
    if (point.periodLabel) return String(point.periodLabel).replace(/^\d+年/, "").replace("第", "W");
    const parts = String(point.date || "").split("-");
    return parts.length === 3 ? `${Number(parts[1])}/${Number(parts[2])}` : point.date;
  };
  const fillId = `liftFill-${large ? "lg" : "sm"}-${Math.round(Math.random() * 1e9)}`;
  const bars = volumes.map((value, index) => {
    const h = height - pad.b - yVol(value);
    return `<rect class="lift-bar" x="${(xAt(index) - barW / 2).toFixed(1)}" y="${yVol(value).toFixed(1)}" width="${barW.toFixed(1)}" height="${Math.max(h, 0).toFixed(1)}" rx="3"></rect>`;
  }).join("");
  return `<div class="lift-chart" data-lift-chart="${large ? "large" : "inline"}">
    <div class="lift-legend"><span class="best">历史最佳 1RM</span><span class="work">工作组均重</span><span class="vol">训练量</span></div>
    <div class="lift-plot">
    <svg viewBox="0 0 ${width} ${height}" data-lift-svg data-pad-l="${pad.l}" data-pad-r="${pad.r}" role="img" aria-label="按次等距平铺的力量进步曲线">
      <defs>
        <linearGradient id="${fillId}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#79f2bf" stop-opacity="0.32"/>
          <stop offset="100%" stop-color="#79f2bf" stop-opacity="0"/>
        </linearGradient>
      </defs>
      ${ticks.map((tick) => `<g class="lift-grid"><line x1="${pad.l}" x2="${width - pad.r}" y1="${yAt(tick).toFixed(1)}" y2="${yAt(tick).toFixed(1)}"></line><text x="${pad.l - 8}" y="${yAt(tick).toFixed(1)}" dy="0.35em">${Math.round(tick * 10) / 10}</text></g>`).join("")}
      ${bars}
      <path class="lift-area" d="${area}" fill="url(#${fillId})"></path>
      <path class="lift-line is-best" d="${bestLine}"></path>
      <path class="lift-line" d="${weightLine}"></path>
      ${weights.map((value, index) => value == null ? "" : `<circle class="lift-hit" data-lift-index="${index}" cx="${xAt(index).toFixed(1)}" cy="${yAt(value).toFixed(1)}" r="16"></circle><circle class="lift-dot${index === active ? " is-active" : ""}" data-lift-index="${index}" cx="${xAt(index).toFixed(1)}" cy="${yAt(value).toFixed(1)}" r="${index === active ? 6.5 : 4.5}"></circle>`).join("")}
      <line class="lift-scrub" x1="${xAt(active).toFixed(1)}" x2="${xAt(active).toFixed(1)}" y1="${pad.t}" y2="${height - pad.b}"></line>
      ${labelIndexes.map((index) => `<text class="lift-x" x="${xAt(index).toFixed(1)}" y="${height - 10}">${escapeHTML(axisLabel(points[index]))}</text>`).join("")}
    </svg>
    <div class="lift-tooltip" hidden>${liftPointDetailMarkup(points[active], { unit, grain, escapeHTML })}</div>
    </div>
  </div>`;
}
